// Is there a release newer than the installed one? Then one line for the assistant; otherwise nothing at all.
// ---- Filled in when the workflow is set up (the assistant does it: docs/updating.md) ----
const INSTALLED = '__VERSION__';      // VERSION from /usr/local/share/assistant/install.conf, e.g. v1.4.0
const REPO = '__GITHUB_REPO__';       // GITHUB_REPO from the same file, e.g. jonjunq/claudia
// -----------------------------------------------------------------------------------------
// Only the numbers of a tag are used: the release title and notes are not passed on, so nothing written in the
// repo reaches the assistant's terminal (it reads the changelog itself, as data).
const parse = v => { const m = String(v || '').match(/^v?(\d+)\.(\d+)\.(\d+)/); return m ? m.slice(1).map(Number) : null; };
const newer = (a, b) => { for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] > b[i]; return false; };
const max = (a, b) => (!a ? b : !b ? a : newer(a, b) ? a : b);
const r = $input.first().json;
if (r.draft || r.prerelease) return [];
const latest = parse(r.tag_name);
if (!latest) throw new Error('The latest release has a tag that is not a version: ' + String(r.tag_name).slice(0, 40));
const mem = $getWorkflowStaticData('global');
const known = max(parse(INSTALLED), parse(mem.reported));
const tag = 'v' + latest.join('.');
if (!known) { mem.reported = tag; return []; }   // nothing to compare with: remember it, report the next one
if (!newer(latest, known)) return [];
mem.reported = tag;                               // one notice per release, whatever the assistant decides
return [{ json: { source: 'claudia-release', text: 'New release ' + tag + ' of ' + REPO + ' (this watch was set up on ' +
  INSTALLED + '; the installed version is in /usr/local/share/assistant/install.conf). Notes: https://github.com/' +
  REPO + '/releases/tag/' + tag } }];
